// Verb trainer: questions per verb, drills that favour weak verbs, mastery from past attempts.
import type { Exercise, Verb, VerbSet } from './content/types'
import type { Attempt } from './db'
import { rng } from './test'

const files = import.meta.glob<VerbSet>('../content/verbs/*.json', { eager: true, import: 'default' })
export const verbSet: VerbSet = Object.values(files)[0]
export const verbs: Verb[] = verbSet.verbs
export const verbById: Record<string, Verb> = Object.fromEntries(verbs.map(v => [v.id, v]))

/** Clip ids: each form with its pronoun ("eu sou"), generated by scripts/content.mjs. */
export const formAudio = (v: Verb, i: number) => `vb-${v.id}-f${i}`

/** Exercise ids look like vb-<verbId>-<kind>-<n>; verb ids are letters only. */
export const verbOf = (exerciseId: string) => (exerciseId.startsWith('vb-') ? exerciseId.split('-')[1] : null)

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
/** Replace the verb form in a sentence with a gap (whole word only). */
export function gapSentence(pt: string, form: string) {
  const re = new RegExp(`(^|[^\\p{L}-])(${escapeRe(form)})(?=$|[^\\p{L}-])`, 'iu')
  const m = pt.match(re)
  return m ? { pt: pt.replace(re, '$1___'), answer: m[2] } : null
}

function shuffle<T>(xs: T[], rand: () => number) {
  const a = [...xs]
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [a[i], a[j]] = [a[j], a[i]] }
  return a
}

export type VerbQuestions = { type: Exercise[]; pick: Exercise[]; gap: Exercise[]; table: Exercise }

/** Every question for one verb, grouped by kind. */
export function verbQuestions(v: Verb, rand: () => number = rng(v.id.length)): VerbQuestions {
  const persons = verbSet.persons
  const type: Exercise[] = v.forms.map((f, i) => ({ id: `vb-${v.id}-type-${i}`, type: 'conjugation', part: 'verbs', verb: v.inf, person: persons[i], answers: [f] }))
  const distinct = [...new Set(v.forms)]
  const pick: Exercise[] = v.forms.map((f, i) => {
    const options = shuffle([f, ...shuffle(distinct.filter(x => x !== f), rand).slice(0, 3)], rand)
    return { id: `vb-${v.id}-pick-${i}`, type: 'choose', part: 'verbs', prompt: `${persons[i]} ___ (${v.inf})`, options, answer: options.indexOf(f) }
  })
  const gap: Exercise[] = v.examples.flatMap((x, k) => {
    const g = gapSentence(x.pt, v.forms[x.person])
    return g ? [{ id: `vb-${v.id}-gap-${k}`, type: 'gap-fill', part: 'verbs', pt: g.pt, en: `${x.en} (${v.inf})`, answers: [g.answer] } as Exercise] : []
  })
  const table: Exercise = { id: `vb-${v.id}-table`, type: 'verb-table', part: 'verbs', verb: v.inf, persons, answers: v.forms }
  return { type, pick, gap, table }
}

// ---------- mastery ----------
export type Mastery = { score: number; seen: number }

/** Share of correct answers in the last 10 attempts per verb. */
export function masteryFrom(attempts: Pick<Attempt, 'exerciseId' | 'correct' | 'at'>[]): Record<string, Mastery> {
  const by: Record<string, boolean[]> = {}
  for (const a of [...attempts].sort((x, y) => x.at.localeCompare(y.at))) {
    const v = verbOf(a.exerciseId)
    if (v) (by[v] ??= []).push(a.correct)
  }
  return Object.fromEntries(Object.entries(by).map(([v, rs]) => {
    const last = rs.slice(-10)
    return [v, { score: last.filter(Boolean).length / last.length, seen: rs.length }]
  }))
}

export const isWeakVerb = (m?: Mastery) => !!m && m.seen >= 3 && m.score < 0.7

/** Higher weight = picked more often: weak verbs most, unseen next, mastered least. */
export function verbWeight(m?: Mastery) {
  if (!m) return 1.5
  if (isWeakVerb(m)) return 3
  return Math.max(0.3, 1 - m.score * 0.7)
}

/** A mixed drill over many verbs, favouring weak ones. */
export function verbDrill(pool: Verb[], mastery: Record<string, Mastery>, length = 15, seed = Date.now()): Exercise[] {
  const rand = rng(seed)
  const out: Exercise[] = []
  const seen = new Set<string>()
  const weights = pool.map(v => verbWeight(mastery[v.id]))
  const total = weights.reduce((a, b) => a + b, 0)
  for (let tries = 0; out.length < length && tries < length * 20; tries++) {
    let r = rand() * total
    let i = 0
    while (r > weights[i] && i < pool.length - 1) r -= weights[i++]
    const q = verbQuestions(pool[i], rand)
    // Mostly single forms and sentences; now and then a whole table.
    const kind = rand() < 0.1 ? [q.table] : shuffle([...q.type, ...q.pick, ...q.gap], rand)
    const x = kind.find(e => !seen.has(e.id))
    if (x) { seen.add(x.id); out.push(x) }
  }
  return out
}

/** Everything for one verb: pick forms, type forms, sentences, then the full table. */
export function focusDrill(v: Verb, seed = Date.now()): Exercise[] {
  const rand = rng(seed)
  const q = verbQuestions(v, rand)
  return [...shuffle(q.pick, rand).slice(0, 2), ...shuffle(q.type, rand), ...q.gap, q.table]
}
